#![cfg(unix)]
//! Offline real Session/queue/log fixtures. The one Transport uses loopback
//! configuration and DisabledCredentials; no test invokes a network method.
use moloch_live_runtime::{dispatch,feedback,package_dispatch};
#[path="../src/collateral_feedback.rs"]mod collateral_feedback;
use collateral_feedback::*;
use baal_transport_service::{Receipt,Scope,Config,Transport,DisabledCredentials,SystemClock,ReadOnlyAuthority,admission::AccountAdmission};
use moloch_replay::session::{Session,ExclusiveLock,atomic_json};
use serde_json::{Value,json};
use std::{fs,path::{Path,PathBuf}};
const T:&str="11111111-1111-4111-8111-111111111111";
const P:&str="22222222-2222-4222-8222-222222222222";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn r(endpoint:String,data:Value,start:i64,end:i64)->Receipt{Receipt{endpoint,status:200,request_started_at:iso(start),received_at:iso(end),data}}
fn snapshot(cash:Value,debt:Value,available:Value,power:Value,at:i64)->(Receipt,Receipt){
 let rows:Vec<_>=[101,102].iter().map(|ex|json!({"profileId":P,"tournamentId":T,"componentId":format!("own-{ex}"),"coveredExchangeIds":[ex],"relationshipIds":[],"outstandingAdvance":if debt==json!(0.4){json!(0.2)}else{json!(0)},"guaranteedPayoutFloor":1,"diagnostic":null})).collect();
 (r(format!("/account?tournamentId={T}"),json!({"id":P,"balance":cash,"availableAdvance":available,"buyingPower":power}),at,at+1),r(format!("/portfolio/collateral?tournamentId={T}"),json!({"availableAdvance":available,"data":rows}),at+2,at+3))
}
fn retain(root:&Path,receipt:&Receipt)->RetainedReceipt{fs::create_dir_all(root.join("receipts")).unwrap();atomic_json(&root.join("receipts").join(format!("{}.json",feedback::digest(receipt).unwrap())),&serde_json::to_value(receipt).unwrap()).unwrap();RetainedReceipt::open(root,receipt,ReceiptStore::Ordinary).unwrap()}
macro_rules! boundary {($f:expr)=>{Boundary{root:&$f.root,owner_lock_path:&$f.owner_path,owner_lease:&$f.lease,transport:&$f.transport,ordinary:&$f.ordinary,packages:&$f.packages}};}
struct F{root:PathBuf,owner_path:PathBuf,lease:ExclusiveLock,transport:Transport,ordinary:dispatch::DispatchLog,packages:package_dispatch::PackageDispatchLog,bank:Session,policy:Value,seed:Value}
impl Drop for F{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{Self::with_unknown(false)}
 fn with_unknown(unknown:bool)->Self{
  let root=std::env::temp_dir().join(format!("collateral-feedback-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(&root).unwrap();
  let owner_path=root.join("owner.lock");let lease=ExclusiveLock::acquire(&owner_path).unwrap();let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into()),("102".into(),"102".into())].into()};
  if unknown{let mut queue=AccountAdmission::open(&root.join("account-queue"),"fixture-account","prior-owner").unwrap();let c=json!({"op":"admit","scope":"fixture-account","now":100,"request":"unrelated","write":true,"binding":{"intent":"unrelated-intent","key":"unrelated-key","payload_hash":"a".repeat(64)},"authorized":true,"lease_valid":true,"permit_valid":true});assert_eq!(queue.command(c).unwrap()["admitted"],true);}
  let transport=Transport::new_for_mock(Config{queue_dir:root.join("account-queue"),account_scope:"fixture-account".into(),scope,maximum_pages:20,writes_enabled:false},Box::new(DisabledCredentials),Box::new(SystemClock),Box::new(ReadOnlyAuthority),"http://127.0.0.1:1/api/v1".into()).unwrap();
  let ordinary=dispatch::DispatchLog::open(&root.join("dispatch.ndjson")).unwrap();let packages=package_dispatch::PackageDispatchLog::open(&root.join("package-dispatch")).unwrap();let policy=json!({"quantity":2,"maximumMarkets":3,"entryStopAt":iso(100000)});let seed=json!({"runId":"collateral-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let mut bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();
  for(i,ex)in ["101","102"].iter().enumerate(){let at=iso(i as i64*2500);bank.accept("books",i as u64+1,&json!({"type":"book","receivedAt":at,"book":{"tournamentId":T,"marketId":ex,"exchangeId":ex,"sequence":"1","sourceAt":at,"requestStartedAt":at,"receivedAt":at,"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}})).unwrap();}
  Self{root,owner_path,lease,transport,ordinary,packages,bank,policy,seed}
 }
 fn baseline(&mut self)->(RetainedReceipt,RetainedReceipt){let(a,c)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let(a,c)=(retain(&self.root,&a),retain(&self.root,&c));let b=boundary!(self);let tx=prepare(&self.bank,&b,Operation::Baseline{after:Snapshot{account:&a,collateral:&c}},&iso(3000)).unwrap();tx.commit(&mut self.bank,&b).unwrap();(a,c)}
 fn actual(&mut self)->(Vec<RetainedReceipt>,Vec<RetainedReceipt>){
  let qs:Vec<_>=self.bank.engine().order_records().into_iter().filter(|q|q["side"]=="YES"&&q["action"]=="buy"&&q["retired"]==false).collect();assert_eq!(qs.len(),2);let(mut acks,mut tapes)=(Vec::new(),Vec::new());
  for q in &qs{let qid=q["id"].as_u64().unwrap();let actual=format!("90{qid}");let ack=r("/orders".into(),json!({"orderId":actual,"exchangeId":q["exchangeId"],"side":"yes","action":"buy","quantity":2,"price":0.4,"totalCost":0.8,"all":{"fullNotionalCost":0.8,"effectiveEntryCost":0.6,"collateralSavings":0.2,"collateralRepayment":0,"redemptionCredit":0,"netBuyingPowerImpact":0.8,"relationshipIds":[],"componentId":format!("own-{}",q["exchangeId"].as_str().unwrap()),"guaranteedPayoutFloorAfter":1,"outstandingAdvanceAfter":0.2}}),5000,6500);
   self.ordinary.append(json!({"kind":"intent","qid":qid,"at":iso(4000)})).unwrap();self.ordinary.append(json!({"kind":"attempt","qid":qid,"at":iso(5000)})).unwrap();self.ordinary.append(json!({"kind":"ack","qid":qid,"receipt":ack,"at":iso(6500)})).unwrap();acks.push(retain(&self.root,&ack));
   let event=feedback::acknowledgment(q,&ack,&iso(6500)).unwrap();self.bank.accept("actual",self.bank.last_source_sequence("actual")+1,&event).unwrap();
  }
  for q in &qs{let qid=q["id"].as_u64().unwrap();let actual=format!("90{qid}");let tape=r(format!("/orders/{actual}/fills?limit=200&tournamentId={T}"),json!({"orderId":actual,"exchangeId":q["exchangeId"],"tournamentId":T,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null},"totalQuantityFilled":2,"data":[{"id":format!("80{qid}"),"price":0.4,"quantity":2,"side":"yes","filledAt":iso(6000)}]}),6600,6700);
   for event in feedback::fills(q,&actual,T,&tape,&iso(6700)).unwrap(){self.bank.accept("actual",self.bank.last_source_sequence("actual")+1,&event).unwrap();}
   self.ordinary.append(json!({"kind":"closed","qid":qid,"fillReceiptHash":feedback::digest(&tape).unwrap(),"at":iso(6700)})).unwrap();tapes.push(retain(&self.root,&tape));
  }(acks,tapes)
 }
}
#[test]fn baseline_allows_only_real_never_sent_reservations_and_survives_replay(){let mut f=F::new();assert_eq!(f.bank.engine().order_records().len(),4);f.baseline();let report=f.bank.engine().report().unwrap();assert_eq!(report["collateralAccounting"]["officialCash"],"1000.000000");assert_eq!(report["collateralAccounting"]["availableAdvanceAdmittedForSizing"],"0.000000");let expected=f.bank.durable_head();let alternate=Session::open_live(&f.root.join("alternate"),&f.policy,&f.seed).unwrap();drop(std::mem::replace(&mut f.bank,alternate));f.bank=Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap();assert_eq!(f.bank.engine().report().unwrap(),report);assert_eq!(f.bank.durable_head(),expected);}
#[test]fn borrowed_principal_is_separate_from_native_cash_and_profit_with_original_tapes(){let mut f=F::new();let(ba,bc)=f.baseline();let(acks,tapes)=f.actual();let(a,c)=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let ar:Vec<_>=acks.iter().collect();let tr:Vec<_>=tapes.iter().collect();let b=boundary!(f);let tx=prepare(&f.bank,&b,Operation::Execution{before:Snapshot{account:&ba,collateral:&bc},after:Snapshot{account:&a,collateral:&c},acknowledgments:&ar,fill_tapes:&tr},&iso(7100)).unwrap();let result=tx.commit(&mut f.bank,&b).unwrap();assert_eq!(result.source_sequence,2);assert_eq!(result.report["cash"],"998.400000");assert_eq!(result.report["realized"],"0.000000");assert_eq!(result.report["collateralAccounting"]["officialCash"],"998.800000");assert_eq!(result.report["collateralAccounting"]["officialDebt"],"0.400000");assert_eq!(f.bank.engine().fills().len(),2);}
#[test]fn authority_uses_only_reconciled_adjustment_and_blocks_pending_fill_economics(){let mut f=F::new();assert_eq!(moloch_live_runtime::authority::reconciled_expected_cash(&f.bank).unwrap(),1_000_000_000);let(ba,bc)=f.baseline();let(acks,tapes)=f.actual();assert!(moloch_live_runtime::authority::reconciled_expected_cash(&f.bank).is_err());let(a,c)=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let ar:Vec<_>=acks.iter().collect();let tr:Vec<_>=tapes.iter().collect();let b=boundary!(f);prepare(&f.bank,&b,Operation::Execution{before:Snapshot{account:&ba,collateral:&bc},after:Snapshot{account:&a,collateral:&c},acknowledgments:&ar,fill_tapes:&tr},&iso(7100)).unwrap().commit(&mut f.bank,&b).unwrap();assert_eq!(moloch_live_runtime::authority::reconciled_expected_cash(&f.bank).unwrap(),998_800_000);assert_eq!(f.bank.engine().wallet.cash,998_400_000);}
#[test]fn global_unrelated_unknown_blocks_baseline_without_account_reads(){let f=F::with_unknown(true);let(a,c)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let old=f.bank.durable_head();assert!(prepare(&f.bank,&boundary!(f),Operation::Baseline{after:Snapshot{account:&a,collateral:&c}},&iso(3000)).is_err());assert_eq!(f.bank.durable_head(),old);}
#[test]fn physical_attempt_even_without_ack_is_not_never_sent(){let mut f=F::new();let qid=f.bank.engine().order_records()[0]["id"].as_u64().unwrap();f.ordinary.append(json!({"kind":"intent","qid":qid})).unwrap();f.ordinary.append(json!({"kind":"attempt","qid":qid})).unwrap();let(a,c)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));assert!(prepare(&f.bank,&boundary!(f),Operation::Baseline{after:Snapshot{account:&a,collateral:&c}},&iso(3000)).is_err());}
#[test]fn changed_bank_after_prepare_does_not_commit_stale_transition(){let mut f=F::new();let(a,c)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let b=boundary!(f);let tx=prepare(&f.bank,&b,Operation::Baseline{after:Snapshot{account:&a,collateral:&c}},&iso(3000)).unwrap();f.bank.accept("tick",1,&json!({"type":"tick","receivedAt":iso(3000)})).unwrap();let head=f.bank.durable_head();assert!(tx.commit(&mut f.bank,&b).is_err());assert_eq!(f.bank.durable_head(),head);}
#[test]fn replaced_original_journal_path_rejects_even_identical_bytes(){let mut f=F::new();let(a,c)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let b=boundary!(f);let tx=prepare(&f.bank,&b,Operation::Baseline{after:Snapshot{account:&a,collateral:&c}},&iso(3000)).unwrap();let path=f.root.join("dispatch.ndjson");fs::rename(&path,f.root.join("dispatch.original")).unwrap();fs::write(&path,b"").unwrap();assert!(tx.commit(&mut f.bank,&b).is_err());}
#[test]fn changed_receipt_bytes_after_prepare_fail_even_with_same_length(){let mut f=F::new();let(a,c)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let original=a.clone();let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let b=boundary!(f);let tx=prepare(&f.bank,&b,Operation::Baseline{after:Snapshot{account:&a,collateral:&c}},&iso(3000)).unwrap();let path=f.root.join("receipts").join(format!("{}.json",feedback::digest(&original).unwrap()));let bytes=fs::read_to_string(&path).unwrap().replace("1000","1001");fs::write(path,bytes).unwrap();let head=f.bank.durable_head();assert!(tx.commit(&mut f.bank,&b).is_err());assert_eq!(f.bank.durable_head(),head);}
#[test]fn incomplete_or_missing_original_fill_tape_cannot_be_replaced_by_ack_totals(){let mut f=F::new();let(ba,bc)=f.baseline();let(acks,tapes)=f.actual();let(a,c)=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let ar:Vec<_>=acks.iter().collect();let tr:Vec<_>=tapes[..1].iter().collect();let old=f.bank.durable_head();assert!(prepare(&f.bank,&boundary!(f),Operation::Execution{before:Snapshot{account:&ba,collateral:&bc},after:Snapshot{account:&a,collateral:&c},acknowledgments:&ar,fill_tapes:&tr},&iso(7100)).is_err());assert_eq!(f.bank.durable_head(),old);}
#[test]fn original_receipts_cannot_come_from_a_replacement_root_or_symlink(){use std::os::unix::fs::symlink;let f=F::new();let(a,_)=snapshot(json!(1000),json!(0),json!(0.5),json!(1000.5),1);let _=retain(&f.root,&a);let link=f.root.join("alias");symlink(f.root.join("receipts"),&link).unwrap();let replacement=f.root.join("replacement");fs::create_dir_all(&replacement).unwrap();symlink(f.root.join("receipts"),replacement.join("receipts")).unwrap();assert!(RetainedReceipt::open(&replacement,&a,ReceiptStore::Ordinary).is_err());}
#[test]fn terminal_passive_partial_fill_after_ack_syncs_cash_without_inventing_gross_advances(){
 let mut f=F::new();let(ba,bc)=f.baseline();let q=f.bank.engine().order_records().into_iter().find(|q|q["side"]=="YES"&&q["action"]=="buy").unwrap();let qid=q["id"].as_u64().unwrap();let actual=format!("90{qid}");
 let ack=r("/orders".into(),json!({"orderId":actual,"exchangeId":q["exchangeId"],"side":"yes","action":"buy","quantity":2,"price":0.4,"all":null}),5000,5100);f.ordinary.append(json!({"kind":"intent","qid":qid})).unwrap();f.ordinary.append(json!({"kind":"attempt","qid":qid})).unwrap();f.ordinary.append(json!({"kind":"ack","qid":qid,"receipt":ack})).unwrap();let original_ack=retain(&f.root,&ack);let e=feedback::acknowledgment(&q,&ack,&iso(5100)).unwrap();f.bank.accept("actual",1,&e).unwrap();
 let tape=r(format!("/orders/{actual}/fills?limit=200&tournamentId={T}"),json!({"orderId":actual,"exchangeId":q["exchangeId"],"tournamentId":T,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null},"totalQuantityFilled":1,"data":[{"id":"810001","price":0.4,"quantity":1,"side":"yes","filledAt":iso(6000)}]}),6600,6700);for e in feedback::fills(&q,&actual,T,&tape,&iso(6700)).unwrap(){f.bank.accept("actual",2,&e).unwrap();}
 let closed=r(format!("/orders/{actual}"),json!({"id":actual,"exchangeId":q["exchangeId"],"tournamentId":T,"side":"yes","action":"buy","priceLimit":0.4,"quantity":2,"quantityFilled":1,"open":false,"terminalReasonCode":"Canceled"}),6500,6550);let e=feedback::terminal(&q,&actual,T,&closed,&tape,&iso(6800)).unwrap().unwrap();f.bank.accept("actual",3,&e).unwrap();f.ordinary.append(json!({"kind":"closed","qid":qid,"fillReceiptHash":feedback::digest(&tape).unwrap()})).unwrap();let original_tape=retain(&f.root,&tape);
 let(a,c)=snapshot(json!(999.6),json!(0),json!(0.5),json!(1000.1),7000);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let acks=[&original_ack];let tapes=[&original_tape];let b=boundary!(f);let tx=prepare(&f.bank,&b,Operation::OrdinaryCashSync{before:Snapshot{account:&ba,collateral:&bc},after:Snapshot{account:&a,collateral:&c},acknowledgments:&acks,fill_tapes:&tapes},&iso(7100)).unwrap();let result=tx.commit(&mut f.bank,&b).unwrap();assert_eq!(result.report["cash"],"999.600000");assert_eq!(result.report["collateralAccounting"]["officialCash"],"999.600000");assert_eq!(result.report["collateralAccounting"]["officialDebt"],"0.000000");assert!(result.report["collateralAccounting"]["cumulativeBorrowed"].is_null());assert!(result.report["collateralAccounting"]["cumulativeRepaid"].is_null());assert_eq!(f.bank.engine().fills().len(),1);assert_eq!(moloch_live_runtime::authority::reconciled_expected_cash(&f.bank).unwrap(),999_600_000);
}
#[test]fn explicit_official_settlement_retires_attributed_lots_without_creating_fills(){
 let mut f=F::new();let(ba,bc)=f.baseline();let(acks,tapes)=f.actual();let(a,c)=snapshot(json!(998.8),json!(0.4),json!(0.1),json!(998.9),7000);let(a,c)=(retain(&f.root,&a),retain(&f.root,&c));let ar:Vec<_>=acks.iter().collect();let tr:Vec<_>=tapes.iter().collect();
 {let b=boundary!(f);prepare(&f.bank,&b,Operation::Execution{before:Snapshot{account:&ba,collateral:&bc},after:Snapshot{account:&a,collateral:&c},acknowledgments:&ar,fill_tapes:&tr},&iso(7100)).unwrap().commit(&mut f.bank,&b).unwrap();}
 let(aa,ac)=snapshot(json!(1000.4),json!(0),json!(0),json!(1000.4),9000);let(aa,ac)=(retain(&f.root,&aa),retain(&f.root,&ac));let rows:Vec<_>=[("101","win",2),("102","loss",0)].iter().map(|(ex,kind,payout)|json!({"id":format!("settled-{ex}"),"type":kind,"createdAt":iso(8000),"exchangeId":ex,"marketId":ex,"settlementOption":"YES","settlementOutcome":null,"shares":2,"avgEntryPrice":null,"costBasis":null,"payout":payout,"realizedPnl":null})).collect();
 let settlements=r("/tournaments/cup/portfolio/settlements?limit=200".into(),json!({"data":rows,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null}}),8100,8200);let settlements=retain(&f.root,&settlements);let ids=vec!["settled-101".into(),"settled-102".into()];let b=boundary!(f);
 let result=prepare(&f.bank,&b,Operation::Settlement{before:Snapshot{account:&a,collateral:&c},after:Snapshot{account:&aa,collateral:&ac},settlements:&settlements,settlement_ids:&ids},&iso(9100)).unwrap().commit(&mut f.bank,&b).unwrap();
 assert_eq!(result.report["ownedCost"],"0.000000");assert_eq!(result.report["cash"],"1000.400000");assert_eq!(result.report["collateralAccounting"]["officialDebt"],"0.000000");assert_eq!(result.report["collateralAccounting"]["actualSettlements"],2);assert_eq!(f.bank.engine().fills().len(),2);
}
